Bardesk_new.prototype.build_common = function () {
    var scope = this;
    var shape = build_shape.square(scope.params.width / units, scope.params.depth / units);


    scope.model.tabletop = new Tabletop({
        width: scope.params.width,
        height: scope.params.thickness,
        depth: scope.params.depth,
        material: scope.params.material
    });


    this.model.tabletop.position.y = this.params.height / units;

    if(scope.params.name == 'bardesk'){
        var leg_geometry = new THREE.CylinderBufferGeometry(25 / units, 25 / units, scope.params.height / units - scope.params.thickness / units, 12);
        scope.model.leg = new THREE.Mesh(leg_geometry, white_mat);
        this.model.leg.position.y = this.params.height / units / 2 - this.params.thickness / units / 2;
        this.model.leg.position.z = this.params.depth / units / 2 - 250 / units;
    } else {

        scope.params.name.variants[0].height = scope.params.height - scope.params.thickness

        scope.model.leg = new Model_new(scope.params.name)
        scope.model.leg.load_model()


        // this.model.leg.position.y = this.params.height / units / 2 - this.params.thickness / units / 2;
        this.model.leg.position.z = this.params.depth / units / 2 - 250 / units;
    }


    if(scope.params.plints.back != false){
        let pb = new Decoration({
            width: scope.params.width,
            height: 30,
            thickness: 20,
            material: scope.params.material,
            model: '/common_assets/models/tp1.fbx'
        })

        scope.model.add(pb)
        pb.position.y = this.model.tabletop.position.y  + 30 / units / 2
        pb.position.z = - scope.params.depth / units / 2 + 20 / units / 2
    }

    if(scope.params.plints.left != false){
        let pb = new Decoration({
            width: scope.params.depth,
            height: 30,
            thickness: 20,
            material: scope.params.material,
            model: '/common_assets/models/tp1.fbx'
        })

        scope.model.add(pb)
        pb.rotation.y = Math.PI / 2;
        pb.position.y = this.model.tabletop.position.y  + 30 / units / 2
        pb.position.x = - scope.params.width / units / 2 + 20 / units / 2
    }

    if(scope.params.plints.right != false){
        let pb = new Decoration({
            width: scope.params.depth,
            height: 30,
            thickness: 20,
            material: scope.params.material,
            model: '/common_assets/models/tp1.fbx'
        })

        scope.model.add(pb)
        pb.rotation.y = -Math.PI / 2;
        pb.position.y = this.model.tabletop.position.y  + 30 / units / 2
        pb.position.x = scope.params.width / units / 2 - 20 / units / 2
    }

    scope.model.leg.visible = scope.params.leg_visible;

    scope.model.add(scope.model.tabletop);
    scope.model.add(scope.model.leg);
};

Bardesk_new.prototype.build_rounded = function () {
    var scope = this;
    var shape = build_shape.rounded_tabletop(scope.params.width / units, scope.params.depth / units, scope.params.radius / units);


    scope.model.tabletop = new Tabletop({
        width: scope.params.width,
        height: scope.params.thickness,
        depth: scope.params.depth,
        material: scope.params.material,
        shape: shape
    });

    if(scope.params.name == 'bardesk'){
        var leg_geometry = new THREE.CylinderBufferGeometry(25 / units, 25 / units, scope.params.height / units - scope.params.thickness / units, 12);
        scope.model.leg = new THREE.Mesh(leg_geometry, white_mat);
        this.model.leg.position.y = this.params.height / units / 2 - this.params.thickness / units / 2;
        this.model.leg.position.z = this.params.depth / units / 2 - 250 / units;
    } else {
        scope.params.name.variants[0].height = scope.params.height - scope.params.thickness

        scope.model.leg = new Model_new(scope.params.name)
        scope.model.leg.load_model()


        // this.model.leg.position.y = this.params.height / units / 2 - this.params.thickness / units / 2;
        this.model.leg.position.z = this.params.depth / units / 2 - 250 / units;
    }




    this.model.tabletop.position.y = this.params.height / units;


    if(scope.params.plints.back != false){
        let pb = new Decoration({
            width: scope.params.width,
            height: 30,
            thickness: 20,
            material: scope.params.material,
            model: '/common_assets/models/tp1.fbx'
        })

        scope.model.add(pb)
        pb.position.y = this.model.tabletop.position.y  + 30 / units / 2
        pb.position.z = - scope.params.depth / units / 2 + 20 / units / 2
    }




    scope.model.leg.visible = scope.params.leg_visible;

    scope.model.add(scope.model.tabletop);
    scope.model.add(scope.model.leg);
};

